# Diagonal hypothesis: a bg cell becomes 1 if it lies on a diagonal ray from some shape cell with clear path, OR on anti-diagonal too?
def diag_ray(I,H,W,bg,shape,r,c):
    # diagonal down-right
    for k in range(1,max(H,W)):
        rr,cc=r+k,c+k
        if cc>=W or rr>=H: break
        if (rr,cc) in shape: return True
    # up-left
    for k in range(1,max(H,W)):
        rr,cc=r-k,c-k
        if rr<0 or cc<0: break
        if (rr,cc) in shape: return True
    # other two diagonals
    for k in range(1,max(H,W)):
        rr,cc=r+k,c-k
        if cc<0 or rr>=H: break
        if (rr,cc) in shape: return True
    for k in range(1,max(H,W)):
        rr,cc=r-k,c+k
        if cc>=W or rr<0: break
        if (rr,cc) in shape: return True
    return False
