from collections import deque
def dist_grid(shape,H,W):
    D=[[H]*W for _ in range(H)]
    q=deque()
    for r in range(H):
        for c in range(W):
            if (r,c) in shape:
                D[r][c]=0;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and D[rr][cc]>D[r][c]+1:
                D[rr][cc]=D[r][c]+1;q.append((rr,cc))
    return D
