def comps(cells,H,W):
    seen=set();out=[]
    for (r,c) in cells:
        if (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c));st=[]
        while q: st.append(q.pop())
        for a,b in st:
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                n=(a+dr,b+dc)
                if 0<=n[0]<H and 0<=n[1]<W and n not in seen and n in cells: seen.add(n);q.append(n)
        rs=[p[0] for p in seen];cs=[p[1] for p in seen]
        r0,r1=min(rs),max(rs);c0,c1=min(cs),max(cs)
        sub=[[1 if (rr,cc) in cells else 0 for cc in range(c0,c1+1)] for rr in range(r0,r1+1)]
        out.append((sub,r0,c0))
    return out
