    seen=[[False]*W for _ in range(H)]
    import collections
    q=collections.deque()
    for i in range(H):
        for j in [0,W-1]:
            if inp[i][j]!=oc and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    for j in range(W):
        for i in [0,H-1]:
            if inp[i][j]!=oc and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and not seen[ni][nj] and inp[ni][nj]!=oc:
